func TestGN13eDecodeTemplateATemplateOfItsCanonicalJson(t *testing.T) {
	value0, err := DecodeTemplate("{\"type\":\"Template\",\"name\":\"page.tpl\",\"body\":[{\"type\":\"Text\",\"value\":\"a \",\"span\":[0,2]},{\"type\":\"Echo\",\"expr\":{\"type\":\"Var\",\"name\":\"b\",\"span\":[5,6]},\"span\":[2,7]}],\"comments\":[]}")
	if err != nil {
		t.Fatalf("GN-13e: %v", err)
	}
	if want := (ast.Template)(ast.Template{Name: "page.tpl", Body: []ast.Node{ast.NodeText{Value: "a ", Span: [2]uint64{0, 2}}, ast.NodeEcho{Expr: ast.ExprVar{Name: "b", Span: [2]uint64{5, 6}}, Span: [2]uint64{2, 7}}}, Comments: []ast.Comment{}}); !sameValue(value0, want) {
		t.Fatalf("GN-13e: %#v is not %#v", value0, want)
	}
}

